Prism.languages.mine={comment:{pattern:/(?:#[^\n]*|\/\/.*|\/\*[\s\S]*?\*\/)/,greedy:!0},filecomment:{pattern:/^#\s.*/m,alias:"comment",greedy:!0},doccomment:{pattern:/\/\/\/.*/,alias:"comment",greedy:!0},keyword:{pattern:/\b(fn|pub|var|const|for|while|loop|return|break|continue|defer|errdefer|test|bench|if|else|match|case|try|catch|throw)\b/,alias:"keyword"},type:{pattern:/\b(int|i8|i16|i32|i64|uint|u8|u16|u32|u64|char|string|bool)\b/,alias:"type"},boolean:{pattern:/\b(true|false)\b/,alias:"boolean"},number:{pattern:/-?\b\d+\b/,alias:"number"},function:{pattern:/\b[a-zA-Z_]\w*(?=\s*\()/,alias:"function"},string:{pattern:/"(?:[^"\\]|\\.)*"/,greedy:!0},variable:{pattern:/\b[a-zA-Z_]\w*\b/},operator:{pattern:/[+\-*/%=!<>?:]+|==|!=|<=|>=|&&|\|\||\.\.\.|\.\./,alias:"operator"},punctuation:{pattern:/[{}[\];(),]/,alias:"punctuation"}};